    //     - Focusable elements should never use `outline` for any other purpose than focus outline
    //     - Use `px` rather than `rem` because these should not scale dynamically
    //   */
    //   /* outline: 3px solid var(--bk-focus-outline-color); */
    //   /* outline-offset: 3px; */
    //   /* border-radius: 3px; */
