  const mergedListBoxRef = mergeRefs<React.ComponentRef<typeof ListBox.ListBox>>(
    listBoxRef,
    refs.setFloating,
    floatingProps.ref as React.Ref<React.ComponentRef<typeof ListBox.ListBox>>,
  );

  const selectedFromInternalSelected = React.useMemo(() => {
