  const selectedItem = useListBoxSelector(s => s.selectedItem);
  const onChange = React.useCallback(() => {}, []);
  return (
    <input
      type="hidden"
      name={name}
      form={form}
      {...inputProps}
      ref={mergeRefs(ref, inputProps?.ref)}
      value={selectedItem ?? ''}
